import math
import struct


def _to_float32(value):
    """Round a float to single precision, the type of LaserScan range fields."""
    try:
        return struct.unpack('f', struct.pack('f', value))[0]
    except OverflowError:
        return math.copysign(math.inf, value)


def count_near(ranges, range_min, range_max, limit):
    """Count finite ranges in inclusive [range_min, range_max] that are <= limit.

    The limit is compared at float32 precision so that a reading equal to the
    limit (e.g. 0.4 stored as float32 0.4000000059...) counts as "at" the limit.
    """
    limit = _to_float32(limit)
    return sum(
        1 for r in ranges
        if math.isfinite(r) and range_min <= r <= range_max and r <= limit
    )

from array import array
import math

import pytest

from scan_watch.logic import count_near

INF = math.inf
NAN = math.nan


def f32(values):
    """Ranges as they arrive in a LaserScan message (float32 array)."""
    return array('f', values)


def test_empty_scan_is_zero():
    assert count_near([], 0.1, 10.0, 1.0) == 0
    assert count_near(f32([]), 0.1, 10.0, 1.0) == 0


def test_non_finite_ranges_are_ignored():
    assert count_near([INF, -INF, NAN], 0.0, INF, INF) == 0


def test_bounds_are_inclusive():
    assert count_near([0.1, 2.0], 0.1, 2.0, 5.0) == 2


def test_ranges_outside_message_bounds_are_ignored():
    assert count_near([0.05, 2.5, -1.0], 0.1, 2.0, 5.0) == 0


def test_limit_is_inclusive():
    assert count_near([0.3, 0.4, 0.5], 0.0, 10.0, 0.4) == 2


def test_limit_equal_to_float32_range_counts():
    # float32(0.4) > float64(0.4); a reading of exactly 0.4 is still "at" the limit.
    assert count_near(f32([0.4, 0.8]), 0.0, 10.0, 0.4) == 1
    assert count_near(f32([0.4, 0.8]), 0.0, 10.0, 0.8) == 2


def test_limit_below_range_min_counts_nothing():
    assert count_near([0.1, 0.2], 0.5, 10.0, 0.3) == 0


@pytest.mark.parametrize('limit, expected', [(0.4, 3), (0.8, 5), (1e300, 7), (-1.0, 0)])
def test_mixed_scan(limit, expected):
    ranges = f32([0.05, 0.1, 0.3, 0.4, 0.5, 0.8, 1.0, 2.0, 2.5, INF, NAN, -INF])
    assert count_near(ranges, 0.1, 2.0, limit) == expected

"""Launch the installed monitor.launch.py and check real near_count output."""
import math
import os
import time
import unittest

from ament_index_python.packages import get_package_share_directory
from launch import LaunchDescription
from launch.actions import IncludeLaunchDescription
from launch.launch_description_sources import PythonLaunchDescriptionSource
import launch_testing
import launch_testing.actions
import pytest
import rclpy
from rclpy.qos import QoSProfile, ReliabilityPolicy
from sensor_msgs.msg import LaserScan
from std_msgs.msg import Int32

NAMESPACE = f'scan_watch_test_{os.getpid()}'
# Counted per limit (range_min=0.1, range_max=2.0):
#   0.4 -> 0.1 0.3 0.4    0.8 -> + 0.5 0.8    1 -> + 1.0
RANGES = [0.05, 0.1, 0.3, 0.4, 0.5, 0.8, 1.0, 2.0, 2.5, math.inf, math.nan, -math.inf]


@pytest.mark.launch_test
@launch_testing.parametrize('limit_arg, expected', [
    (None, 3),     # limit:= omitted -> config/monitor.yaml (0.4)
    ('0.8', 5),    # explicit override
    ('1', 6),      # integer-looking override is accepted
])
def generate_test_description(limit_arg, expected):
    launch_args = {'namespace': NAMESPACE}
    if limit_arg is not None:
        launch_args['limit'] = limit_arg
    monitor = IncludeLaunchDescription(
        PythonLaunchDescriptionSource(os.path.join(
            get_package_share_directory('scan_watch'), 'launch', 'monitor.launch.py')),
        launch_arguments=launch_args.items())
    return LaunchDescription([monitor, launch_testing.actions.ReadyToTest()])


class TestMonitor(unittest.TestCase):

    @classmethod
    def setUpClass(cls):
        rclpy.init()

    @classmethod
    def tearDownClass(cls):
        rclpy.shutdown()

    def setUp(self):
        self.node = rclpy.create_node('scan_watch_tester')

    def tearDown(self):
        self.node.destroy_node()

    def _count_for_scan(self, reliability, timeout=15.0):
        received = []
        self.node.create_subscription(
            Int32, f'/{NAMESPACE}/near_count', lambda m: received.append(m.data), 10)
        pub = self.node.create_publisher(
            LaserScan, f'/{NAMESPACE}/scan', QoSProfile(depth=5, reliability=reliability))
        scan = LaserScan(range_min=0.1, range_max=2.0, ranges=RANGES)
        deadline = time.monotonic() + timeout
        # Republish until discovery completes and a result comes back.
        while not received and time.monotonic() < deadline:
            pub.publish(scan)
            rclpy.spin_once(self.node, timeout_sec=0.2)
        self.assertTrue(received, 'no near_count received')
        return received[-1]

    def test_node_is_namespaced(self):
        deadline = time.monotonic() + 10.0
        names = []
        while time.monotonic() < deadline:
            names = self.node.get_node_names_and_namespaces()
            if ('scan_watch', f'/{NAMESPACE}') in names:
                break
            time.sleep(0.2)
        self.assertIn(('scan_watch', f'/{NAMESPACE}'), names)

    def test_best_effort_publisher(self, expected):
        self.assertEqual(self._count_for_scan(ReliabilityPolicy.BEST_EFFORT), expected)

    def test_reliable_publisher(self, expected):
        self.assertEqual(self._count_for_scan(ReliabilityPolicy.RELIABLE), expected)


@launch_testing.post_shutdown_test()
class TestShutdown(unittest.TestCase):

    def test_exit_code(self, proc_info):
        launch_testing.asserts.assertExitCodes(
            proc_info, allowable_exit_codes=[0, -2, -15])

